INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422724, 16321, 'France 24', 'en', 'EU wants Meta to extend US teen safety restrictions to Europe', 'https://www.france24.com/en/eu-wants-meta-to-extend-us-teen-safety-restrictions-to-europe', 'The EU is pressing Meta to introduce the same protections for under-18s in Europe that it agreed to in a landmark US settlement, including screen-time limits and stronger parental controls on Facebook and Instagram. Brussels is also demanding additional measures.', 'https://s.france24.com/media/display/64416fdc-a2b9-11f1-844a-005056bfb2b6/w:1024/p:16x9/EN-20260828-070706-070907-CS.jpg', '2026-08-28T09:13:28+00:00', '2026-08-28T12:49:23.870603'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
