INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425492, 16321, 'Euronews', 'en', 'No more doomscrolling till dawn: Meta sets curfews for teen Instagram use', 'http://www.euronews.com/next/2026/08/28/no-more-doomscrolling-till-dawn-meta-sets-curfews-for-teen-instagram-use', 'Meta''s Instagram and Facebook will soon lock kids out at midnight and cap their scrolling at two hours a day, part of an $18bn (€15.4bn) settlement with 48 US states.', '', '2026-08-28T09:38:27+00:00', '2026-08-28T12:54:11.331152'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
