INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427271, 16321, 'The Guardian', 'en', 'An $18bn settlement – and Zuckerberg barely blinked. The tech titans must be stripped of their power, and soon', 'https://www.theguardian.com/commentisfree/2026/aug/28/meta-18bn-settlement-mark-zuckerberg-tech-titans-power-harm', 'Those who said Meta harms children struck a blow, but the ability of big tech to gouge profits and cause harm is barely diminished. That’s the battle to come Follow the money. If you want to know how the tech giant Meta really feels about the $18bn it agreed to fork out to end a landmark lawsuit against it – an outcome widely hailed as a victory for campaigners – just look at its share price . It didn’t go down when word came on Wednesday that Meta had settled with the 29 US states that had argued that the company’s Facebook and Instagram platforms harmed children. On the contrary, Meta stock ', 'https://i.guim.co.uk/img/media/fee88091f23cfe465a5f30897be731a763eb50f9/259_0_5955_4768/master/5955.jpg?width=140&quality=85&auto=format&fit=max&s=cc7f87ff9c0fc3763afb22b41c4c4187', '2026-08-28T16:10:15+00:00', '2026-08-29T00:03:22.504385'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
